SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C60/inputs/native_group_generators.m";
root:="work/deg10/continuation_20261031b/C60/";Y:=MDX1(30,GF(7));C:=Curve(Y);F0,mp:=AlgorithmicFunctionField(FunctionField(C));F:=RationalExtensionRepresentation(F0);assert Genus(F)eq 9;os:=[Type(o)eq PlcCrvElt select Divisor(o)else o:o in CuspOrbitsQ(Y)];cs:=Cusps(Y);c0:=Support([o:o in os|Degree(o)eq 1][1])[1];A:=FunctionFieldDivisor(Divisor(c0));
ClassGroupAbelianInvariants(F:ReductionDivisor:=A,Proof:=true);assert F`cld`proven;MDProvenClassGroupGenerators(F);G,_,phi:=ClassGroup(F);fb:=Reverse([v`place:v in F`cld`fb]);fc:=[phi(Divisor(p)):p in fb];hg:=[phi(FunctionFieldDivisor(o)-Degree(o)*A):o in os];H:=sub<G|hg>;assert Invariants(G)eq[4,4,4,136,16320,0]and Invariants(H)eq[4,8160];coords:=[F!mp(FunctionField(C).i):i in[1,2]];cp:=[Support(FunctionFieldDivisor(Divisor(p)))[1]:p in cs];cc:=[phi(Divisor(p)-Degree(p)*A):p in cp];OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);
function ER(v)return [[Integers()!a:a in Coefficients(Numerator(v))],[Integers()!a:a in Coefficients(Denominator(v))]];end function;
function EF(v)return [ER(a):a in Eltseq(F!v)];end function;
function PD(p)return [*Degree(p),Order(Ideal(p))eq OF select 1 else 0,[EF(v):v in Basis(Ideal(p))]*];end function;
sp,ss:=Support(A);assert #sp eq 1 and ss[1]eq 1;out:=[*[ER(v):v in Coefficients(DefiningPolynomial(F))],[Order(Ideal(p))eq OF select 1 else 0:p in fb],[Degree(p):p in fb],[[EF(v):v in Basis(Ideal(p))]:p in fb],[Eltseq(v):v in fc],[Eltseq(v):v in Rows(RelationMatrix(G))],[EF(v):v in coords],Index(fb,sp[1]),[Degree(p):p in cp],[Eltseq(v):v in cc],[PD(p):p in cp],PD(sp[1]),[Eltseq(v):v in hg]*];Write(root cat "target30_proven_picard.m",Sprint(out):Overwrite:=true);print "D31B_C60_TARGET30_PROVEN_COMPLETE",Invariants(G),Invariants(H),#fb,Cputime(tt);quit;
